-- 02_projects.sql
-- Tracks user-created projects inside the PRISM application.

CREATE TABLE IF NOT EXISTS public.projects (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title TEXT NOT NULL,
  owner_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- CODE WALKTHROUGH
-- 1. Each row represents one project and gets a UUID primary key generated by PostgreSQL.
-- 2. owner_id references the profile that owns the project; deleting that profile cascades to its projects.
-- 3. created_at and updated_at record when the project row was created or last changed.
